const { JSDOM, VirtualConsole } = require('jsdom');

const BASE = 'http://127.0.0.1:5055/#/porsequencia';
const wait = (ms) => new Promise((r) => setTimeout(r, ms));
let falhas = 0;

function check(nome, cond, detalhe) {
  if (cond) {
    console.log('ok   ' + nome);
  } else {
    falhas += 1;
    console.log('FALHA ' + nome + (detalhe ? ' :: ' + detalhe : ''));
  }
}

async function carregar(opcoes) {
  const vc = new VirtualConsole();
  const erros = [];
  vc.on('jsdomError', (e) => erros.push(e.message));
  const dom = await JSDOM.fromURL(BASE, Object.assign({
    resources: 'usable',
    runScripts: 'dangerously',
    pretendToBeVisual: true,
    virtualConsole: vc,
  }, opcoes || {}));
  const w = dom.window;
  for (let i = 0; i < 80 && !w.angular; i++) await wait(250);
  return { dom, w, erros };
}

async function esperar(fn, timeout, intervalo) {
  const limite = Date.now() + (timeout || 20000);
  while (Date.now() < limite) {
    const valor = fn();
    if (valor) return valor;
    await wait(intervalo || 200);
  }
  return fn();
}

function texto(w) {
  return w.document.body.textContent.replace(/\s+/g, ' ');
}

function preencher(w, valor) {
  const input = w.document.querySelector('form input');
  input.value = valor;
  input.dispatchEvent(new w.Event('input', { bubbles: true }));
}

function submeter(w) {
  const form = w.document.querySelector('form');
  form.dispatchEvent(new w.Event('submit', { bubbles: true, cancelable: true }));
}

(async () => {
  const { dom, w } = await carregar();
  check('angular carregou', !!w.angular);
  const seis = await esperar(() => w.document.querySelectorAll('.acordes-container').length >= 6
    && w.document.querySelectorAll('.acordes-container').length);
  check('catalogo do backend lista 6 sequencias', seis === 6, String(seis));
  check('formulario de cadastro presente', !!w.document.querySelector('form input'));
  check('botao Cadastrar presente', /Cadastrar/.test(texto(w)));
  check('sequencia Em,G aparece', /Em/.test(texto(w)));
  check('erro de catalogo ausente', !/Não foi possível carregar/.test(texto(w)));

  preencher(w, 'Am, F, C, G');
  submeter(w);
  const sete = await esperar(() => w.document.querySelectorAll('.acordes-container').length === 7);
  check('cadastro 201 adiciona a setima sequencia', !!sete);
  const cards = await esperar(() => w.document.querySelectorAll('.music-card').length);
  check('busca dispara e mostra resultados', cards > 0, String(cards));
  check('ng-hide de diferenca removido (cards visiveis)', cards > 0);
  check('input limpo apos cadastro', w.document.querySelector('form input').value === '');
  check('erro de busca ausente', !/Ops! Algo errado/.test(texto(w)));

  preencher(w, 'Bm, G, D, A');
  submeter(w);
  const duplicata = await esperar(() => /sequencia ja cadastrada \(id 0\)/.test(texto(w)));
  check('duplicata mostra mensagem com id existente', !!duplicata, texto(w).slice(-200));
  check('duplicata nao cria setima+1 sequencia', w.document.querySelectorAll('.acordes-container').length === 7);

  preencher(w, 'Zz, Zz');
  submeter(w);
  const vazio = await esperar(() => /Nenhuma música encontrada/.test(texto(w)));
  check('busca sem resultados mostra estado vazio', !!vazio, texto(w).slice(-200));
  check('busca sem resultados adiciona a sequencia', w.document.querySelectorAll('.acordes-container').length === 8);
  w.close();

  // Estado de carregamento com "rede lenta" (XHR atrasado).
  const lento = await carregar({
    beforeParse(window) {
      const aberto = window.XMLHttpRequest.prototype.open;
      const enviar = window.XMLHttpRequest.prototype.send;
      window.XMLHttpRequest.prototype.open = function (metodo, url) {
        this.__url = String(url);
        return aberto.apply(this, arguments);
      };
      window.XMLHttpRequest.prototype.send = function () {
        const args = arguments;
        const url = this.__url || '';
        const atrasar = url.indexOf('sequencias') !== -1 || url.indexOf('similares') !== -1;
        if (atrasar) {
          setTimeout(() => enviar.apply(this, args), 1200);
        } else {
          enviar.apply(this, args);
        }
      };
    },
  });
  const carregando = await esperar(() => /Carregando sequências/.test(texto(lento.w)), 5000, 100);
  check('estado de carregamento do catalogo aparece', !!carregando);
  const seisLento = await esperar(() => lento.w.document.querySelectorAll('.acordes-container').length >= 6);
  check('catalogo carrega depois do atraso', !!seisLento);
  lento.w.document.querySelector('.acordes-container').dispatchEvent(
    new lento.w.Event('click', { bubbles: true }));
  const buscando = await esperar(() => /Buscando\.\.\./.test(texto(lento.w)), 5000, 100);
  check('estado Buscando aparece', !!buscando);
  const cardsLento = await esperar(() => lento.w.document.querySelectorAll('.music-card').length);
  check('resultados chegam depois do atraso', cardsLento > 0, String(cardsLento));
  lento.w.close();

  // Erro do catalogo + Tentar de novo, bloqueando GET /sequencias.
  const comErro = await carregar({
    beforeParse(window) {
      const aberto = window.XMLHttpRequest.prototype.open;
      window.XMLHttpRequest.prototype.open = function (metodo, url) {
        if (String(url).indexOf('sequencias') !== -1) {
          throw new Error('bloqueado no teste');
        }
        return aberto.apply(this, arguments);
      };
    },
  });
  const erro = await esperar(() => /Não foi possível carregar as sequências/.test(texto(comErro.w)));
  check('erro do catalogo aparece', !!erro, texto(comErro.w).slice(-200));
  const retry = await esperar(() => /Tentar de novo/.test(texto(comErro.w)));
  check('botao Tentar de novo aparece', !!retry);
  comErro.w.document.querySelector('button.btn-default').dispatchEvent(
    new comErro.w.Event('click', { bubbles: true }));
  const erroDeNovo = await esperar(() => /Não foi possível carregar as sequências/.test(texto(comErro.w)), 5000);
  check('Tentar de novo refaz a chamada e mantem o erro visivel', !!erroDeNovo);
  comErro.w.close();

  console.log(falhas === 0 ? 'TODOS OS CHECKS OK' : (falhas + ' CHECK(S) FALHARAM'));
  process.exit(falhas === 0 ? 0 : 1);
})().catch((e) => {
  console.error('FALHOU', e);
  process.exit(1);
});

