import json, urllib.parse, urllib.request

def paginas(param):
    ids = []
    for p in range(1, 6):
        url = 'http://127.0.0.1:8080/similares?sequencia=%s&pagina=%d' % (
            urllib.parse.quote(param), p)
        with urllib.request.urlopen(url) as r:
            itens = json.load(r)
        ids.extend(i['id_unico_musica'] for i in itens)
        if not itens:
            break
    return set(ids)

a = paginas('Am,F,C,G')
b = paginas('AmFCG')
print('Am,F,C,G:', len(a), 'AmFCG:', len(b), 'mesmo conjunto:', a == b)
