cd /tmp/opencode/frontend-verify && node - <<'JS'
const { JSDOM, VirtualConsole } = require('jsdom');
const wait = (ms) => new Promise(r => setTimeout(r, ms));
(async () => {
  const dom = await JSDOM.fromURL('http://127.0.0.1:8080/#/porsequencia', {
    resources: 'usable', runScripts: 'dangerously', pretendToBeVisual: true,
    virtualConsole: new VirtualConsole()
  });
  const w = dom.window;
  for (let i = 0; i < 80 && !w.angular; i++) await wait(250);
  let seqs = [];
  for (let i = 0; i < 80; i++) {
    seqs = Array.from(w.document.querySelectorAll('.acordes-container'));
    if (seqs.length >= 7) break;
    await wait(250);
  }
  console.log('UI container: catalogo com', seqs.length, 'sequencias');
  const alvo = seqs[seqs.length - 1];
  console.log('UI container: ultima sequencia', alvo.textContent.replace(/\s+/g, ''));
  alvo.dispatchEvent(new w.Event('click', { bubbles: true }));
  let cards = 0;
  for (let i = 0; i < 80; i++) {
    cards = w.document.querySelectorAll('.music-card').length;
    if (cards > 0) break;
    await wait(250);
  }
  console.log('UI container: resultados da sequencia nova =', cards);
  w.close();
  process.exit(cards > 0 ? 0 : 1);
})().catch(e => { console.error(e); process.exit(1); });
